import{_ as a,c as e,o as t,a4 as i}from"./chunks/framework.CpVK_f0P.js";const _=JSON.parse('{"title":"学习原则","description":"","frontmatter":{},"headers":[],"relativePath":"method/learning-principles.md","filePath":"method/learning-principles.md"}'),o={name:"method/learning-principles.md"},l=i('<h1 id="学习原则" tabindex="-1">学习原则 <a class="header-anchor" href="#学习原则" aria-label="Permalink to &quot;学习原则&quot;">​</a></h1><h2 id="输出驱动-而不是资料驱动" tabindex="-1">输出驱动，而不是资料驱动 <a class="header-anchor" href="#输出驱动-而不是资料驱动" aria-label="Permalink to &quot;输出驱动，而不是资料驱动&quot;">​</a></h2><p>学习英语的目的是能说、能用，不是收集笔记和教材。每一次学习都应该有输出环节：复述、造句、录音。如果一次训练没有任何输出，说明训练方式需要调整。</p><h2 id="少量表达-反复调用" tabindex="-1">少量表达，反复调用 <a class="header-anchor" href="#少量表达-反复调用" aria-label="Permalink to &quot;少量表达，反复调用&quot;">​</a></h2><p>不要一次记 50 个短语。每次训练只提炼 3～5 个表达，反复用它们造句、替换、复述，直到能主动想起来。能稳定使用 10 个表达，比&quot;见过 200 个&quot;有价值得多。</p><h2 id="优先说正确的简单句" tabindex="-1">优先说正确的简单句 <a class="header-anchor" href="#优先说正确的简单句" aria-label="Permalink to &quot;优先说正确的简单句&quot;">​</a></h2><p>想不到复杂句的时候，主动降级为简单句。能够连续说出正确的简单句，比卡在复杂句上更重要。</p><p>例如：</p><ul><li>复杂想法：Although Harry was late, Susan was still happy to see him.</li><li>简单表达：Harry was late, but Susan was happy to see him.</li><li>更简单：Harry was late. Susan was still happy to see him.</li></ul><h2 id="不逐字翻译中文" tabindex="-1">不逐字翻译中文 <a class="header-anchor" href="#不逐字翻译中文" aria-label="Permalink to &quot;不逐字翻译中文&quot;">​</a></h2><p>不要在脑子里先想中文再翻译。用已经会的英语句式去表达，允许意思不完全精确，只要能交流就行。</p><h2 id="固定句式需要替换练习" tabindex="-1">固定句式需要替换练习 <a class="header-anchor" href="#固定句式需要替换练习" aria-label="Permalink to &quot;固定句式需要替换练习&quot;">​</a></h2><p>光记住一个句式不够，必须用不同的词替换练习。例如：</p><ul><li>ask someone how to get to... <ul><li>I asked him how to get to the station.</li><li>She asked me how to fix the problem.</li><li>He asked the manager how to submit the report.</li></ul></li></ul><h2 id="只记录真实遇到的问题" tabindex="-1">只记录真实遇到的问题 <a class="header-anchor" href="#只记录真实遇到的问题" aria-label="Permalink to &quot;只记录真实遇到的问题&quot;">​</a></h2><p>不要提前整理&quot;可能会犯的错&quot;。只有在实际训练中暴露的问题才有记录价值。</p><h2 id="不把仓库做成语法百科" tabindex="-1">不把仓库做成语法百科 <a class="header-anchor" href="#不把仓库做成语法百科" aria-label="Permalink to &quot;不把仓库做成语法百科&quot;">​</a></h2><p>语法知识随用随查。这个仓库只记录与当前输出训练直接相关的语法错误和对应的最小知识。</p><h2 id="允许删除已经过时的内容" tabindex="-1">允许删除已经过时的内容 <a class="header-anchor" href="#允许删除已经过时的内容" aria-label="Permalink to &quot;允许删除已经过时的内容&quot;">​</a></h2><p>笔记不是越多越好。如果某个内容已经掌握、过时、或者不再符合当前目标，就删掉。仓库应该保持精简。</p>',20),r=[l];function h(s,n,d,p,c,u){return t(),e("div",null,r)}const q=a(o,[["render",h]]);export{_ as __pageData,q as default};
